// Some portions generated by Codex
package org.eclipse.rdf4j.federated.util;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.HashSet;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.federated.algebra.ConjunctiveFilterExpr;
import org.eclipse.rdf4j.federated.algebra.FilterExpr;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.And;
import org.eclipse.rdf4j.query.algebra.Compare;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

class FilterUtilsTest {

	@Test
	void conjunctionConversionKeepsBothDistinctPredicatesAndTheirOwners() throws Exception {
		FilterExpr lower = predicate(5, Compare.CompareOp.GT);
		FilterExpr upper = predicate(10, Compare.CompareOp.LT);
		ConjunctiveFilterExpr conjunction = new ConjunctiveFilterExpr(List.of(lower, upper));
		var lowerParent = lower.getExpression().getParentNode();
		var upperParent = upper.getExpression().getParentNode();

		And converted = (And) FilterUtils.toFilter(conjunction);

		assertThat(((Compare) converted.getLeftArg()).getOperator()).isEqualTo(Compare.CompareOp.GT);
		assertThat(((Compare) converted.getRightArg()).getOperator()).isEqualTo(Compare.CompareOp.LT);
		assertThat(converted.getLeftArg()).isNotSameAs(lower.getExpression());
		assertThat(converted.getRightArg()).isNotSameAs(upper.getExpression());
		assertThat(lower.getExpression().getParentNode()).isSameAs(lowerParent);
		assertThat(upper.getExpression().getParentNode()).isSameAs(upperParent);
	}

	private FilterExpr predicate(int value, Compare.CompareOp operator) {
		return new FilterExpr(new Compare(Var.of("value"),
				new ValueConstant(SimpleValueFactory.getInstance().createLiteral(value)), operator),
				new HashSet<>(Set.of("value")));
	}
}
